      "card_ids": ["C13"],
      "claim": "Trihexyphenidyl, the closest retrieved analog, is an anticholinergic shown by PET studies to penetrate the blood-brain barrier easily.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Biperiden, another anticholinergic analog, crosses the blood-brain barrier without difficulty, with a reported brain-to-plasma ratio of 7-12.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Bepotastine, a close analog, showed only 16.6% brain H1 receptor occupancy by human PET, indicating limited CNS access and arguing against meaningful penetration.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most relevant anticholinergic analogs show robust brain penetration, while some antihistamine-like analogs show low CNS occupancy; overall direct CNS-penetrant evidence supports meaningful access.",
